function crc(b){let c=0xffffffff;for(const v of b){c^=v;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
function chunk(type,b){const t=Buffer.from(type),r=Buffer.alloc(b.length+12);r.writeUInt32BE(b.length);t.copy(r,4);b.copy(r,8);r.writeUInt32BE(crc(Buffer.concat([t,b])),b.length+8);return r;}
const pngCache=new Map();
function png(rect,color,w=128,h=192){const key=JSON.stringify([rect,color,w,h]);if(pngCache.has(key))return pngCache.get(key);const raw=Buffer.alloc((w*4+1)*h),head=Buffer.alloc(13);head.writeUInt32BE(w);head.writeUInt32BE(h,4);head[8]=8;head[9]=6;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(x>=rect[0]&&x<rect[0]+rect[2]&&y>=rect[1]&&y<rect[1]+rect[3])for(let i=0;i<4;i++)raw[y*(w*4+1)+1+x*4+i]=color[i];const result='data:image/png;base64,'+Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',head),chunk('IDAT',zlib.deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]).toString('base64');pngCache.set(key,result);return result;}
